#pragma once

#include <array>
#include <vector>

#include "risc/memory/memory.hpp"
#include "risc/micro/control/micro_decode_unit.hpp"
#include "risc/micro/control/microinstruction.hpp"
#include "risc/micro/control/switch_unit.hpp"
#include "risc/micro/datapath/datapath.hpp"

namespace risc::micro {

// Figure 9.25: the µcontrol unit (vertical microprogramming)
class MicroControlUnit {
private:
    MicroDecodeUnit micro_decode;

    // Execute unit: applies the control signals generated by the decode unit to the datapath
    void apply_signals(const MicroControlSignals& s, Datapath& datapath, memory::Memory& memory) {
        if (s.loadIR) {
            datapath.fetch.load_ir(memory.read_word(datapath.fetch.fetch_address()));
        }
        if (s.decode) {
            datapath.decode.decode(datapath.fetch.ir, datapath.fetch.pc);
        }
        if (s.transfer) {
            datapath.transfer(s.src, s.dest, s.mux, s.imm);
        }
        if (datapath.run_args(s.args, memory)) {
            halted = true;
        }
    }

    // µfetch multiplexer (Table 9.9)
    unsigned next_upc(const MicroControlSignals& s, const Datapath& datapath) const {
        if (s.next == MicroPCMux::Switch) {
            return switch_unit.get_start_address(datapath.fetch.ir);
        }
        if (s.next == MicroPCMux::BranchTarget) {
            return s.branchTarget;
        }
        if (s.next == MicroPCMux::BranchIfMBranch && datapath.isMBranch) {
            return s.branchTarget;
        }
        return (upc + 1) % MICROPROGRAM_SIZE;
    }

public:
    unsigned upc = 0; // µpc
    std::array<MicroWord, MICROPROGRAM_SIZE> microprogram{}; // microprogram memory
    SwitchUnit switch_unit;
    MicroControlSignals signals; // signals of the last microinstruction (for display)
    bool halted = false;

    void reset() {
        upc = 0;
        signals = MicroControlSignals{};
        halted = false;
    }

    // Store microcode in the microprogram memory, starting at address 0
    void load(const std::vector<Microinstruction>& microcode) {
        for (unsigned i = 0; i < microcode.size(); i++) {
            microprogram[i] = encode(microcode[i]);
        }
    }

    // One cycle: read the microinstruction at µpc, decode it, apply its signals, pick the next µpc
    void step(Datapath& datapath, memory::Memory& memory) {
        if (halted) {
            return;
        }
        MicroWord word = microprogram[upc];
        signals = micro_decode.decode(word);
        apply_signals(signals, datapath, memory);
        upc = next_upc(signals, datapath);
    }
};
}
